// src/pages/driver/LaporanKerusakanPage.js
import React, { useState, useRef } from 'react';
import { supabase, uploadFile, getPublicUrl } from '../../lib/supabase';
import { useAuth } from '../../context/AuthContext';
import DriverLayout from '../../components/layout/DriverLayout';
import toast from 'react-hot-toast';

const KATEGORI = [
  { label:'Mesin & Transmisi', icon:'⚙️', items:['Mesin Mati / Tidak Mau Hidup','Mesin Overheat','Mesin Brebet','Oli Mesin Bocor','Transmisi Bermasalah','Kopling Slip','Aki Soak'] },
  { label:'Ban & Roda',        icon:'🔄', items:['Ban Bocor / Kempes','Ban Pecah','Velg Bengkok','Mur Roda Kendur'] },
  { label:'Rem',               icon:'🛑', items:['Rem Blong / Tidak Pakem','Rem Bunyi / Kasar','Rem Tangan Tidak Berfungsi','Minyak Rem Habis'] },
  { label:'Lampu & Kelistrikan',icon:'💡',items:['Lampu Depan Mati','Lampu Belakang Mati','Lampu Sein Mati','Panel Dashboard Mati','AC Tidak Dingin','Wiper Tidak Berfungsi'] },
  { label:'Bodi & Karoseri',   icon:'🚛', items:['Pintu Tidak Bisa Menutup','Kaca Pecah / Retak','Terpal / Wing Box Rusak','Spion Rusak / Lepas'] },
  { label:'Bahan Bakar',       icon:'⛽', items:['Kehabisan BBM','Tangki BBM Bocor','Filter BBM Tersumbat'] },
  { label:'Lainnya',           icon:'🔧', items:['Kerusakan Lainnya (isi manual)'] },
];

const URGENSI = [
  { value:'kritis', label:'Kritis',  desc:'Unit tidak bisa jalan', icon:'🔴', border:'#fca5a5', bg:'#fff1f2', color:'#7f1d1d' },
  { value:'sedang', label:'Sedang',  desc:'Perlu segera diperbaiki', icon:'🟡', border:'#fcd34d', bg:'#fffbeb', color:'#92400e' },
  { value:'ringan', label:'Ringan',  desc:'Masih bisa beroperasi', icon:'🔵', border:'#93c5fd', bg:'#eff6ff', color:'#1e3a8a' },
];

export default function LaporanKerusakanPage() {
  const { profile } = useAuth();
  const [step, setStep]             = useState(1);
  const [katOpen, setKatOpen]       = useState(null);
  const [jenis, setJenis]           = useState('');
  const [jenisCustom, setJC]        = useState('');
  const [urgensi, setUrgensi]       = useState('');
  const [deskripsi, setDeskripsi]   = useState('');
  const [fotos, setFotos]           = useState([]);
  const [lokasi, setLokasi]         = useState('');
  const [gpsLoad, setGPS]           = useState(false);
  const [saving, setSaving]         = useState(false);
  const [done, setDone]             = useState(false);
  const fileRef = useRef();

  function ambilGPS() {
    if (!navigator.geolocation) { toast.error('GPS tidak tersedia'); return; }
    setGPS(true);
    navigator.geolocation.getCurrentPosition(
      pos => { setLokasi(`${pos.coords.latitude.toFixed(5)}, ${pos.coords.longitude.toFixed(5)}`); toast.success('GPS berhasil'); setGPS(false); },
      () => { toast.error('GPS gagal. Isi manual.'); setGPS(false); }, { timeout:10000 }
    );
  }

  function handleFoto(e) {
    const files = Array.from(e.target.files);
    if (fotos.length + files.length > 5) { toast.error('Maks 5 foto'); return; }
    setFotos(prev => [...prev, ...files.map(f => ({ file:f, preview:URL.createObjectURL(f) }))]);
    e.target.value = '';
  }

  async function handleSubmit() {
    if (fotos.length === 0) { toast.error('Upload minimal 1 foto'); return; }
    if (!lokasi.trim())     { toast.error('Lokasi wajib diisi'); return; }
    setSaving(true);
    try {
      const urls = [];
      for (const { file } of fotos) {
        const path = await uploadFile('kerusakan-photos', file, profile.id);
        urls.push(getPublicUrl('kerusakan-photos', path));
      }

      const { data: unit } = await supabase.from('units').select('id').eq('nopol', profile.nopol_assign).single();
      if (!unit) { toast.error('Unit tidak ditemukan'); return; }

      const finalJenis = jenis === 'Kerusakan Lainnya (isi manual)' ? jenisCustom : jenis;

      const { error } = await supabase.from('laporan_kerusakan').insert({
        unit_id:   unit.id,
        driver_id: profile.id,
        jenis:     finalJenis,
        deskripsi: `[${urgensi.toUpperCase()}] ${deskripsi}`,
        foto_urls: urls,
        koordinat: lokasi,
        status:    'Dilaporkan',
      });
      if (error) throw error;

      // Notif ke admin
      const { data: admins } = await supabase.from('users').select('id').eq('role','admin');
      for (const a of (admins||[])) {
        await supabase.from('notifikasi').insert({
          user_id: a.id,
          judul: `🔧 Kerusakan — ${profile.nopol_assign}`,
          isi:   `${finalJenis} (${urgensi}). Driver: ${profile.nama}`,
          tipe:  'spk',
        });
      }

      setDone(true);
      toast.success('Laporan berhasil dikirim!');
    } catch(e) { toast.error('Gagal: '+e.message); }
    finally { setSaving(false); }
  }

  // Done screen
  if (done) return (
    <DriverLayout title="Laporan Kerusakan" back>
      <div style={{ padding:24, textAlign:'center' }}>
        <div style={{ width:80, height:80, background:'#d1fae5', borderRadius:'50%', display:'flex', alignItems:'center', justifyContent:'center', fontSize:40, margin:'20px auto 16px' }}>✅</div>
        <h2 style={{ fontSize:18, fontWeight:700, marginBottom:6 }}>Laporan Terkirim!</h2>
        <p style={{ fontSize:12, color:'#74777f', marginBottom:20 }}>Admin akan segera menindaklanjuti</p>
        <div style={{ background:'#fff', border:'1px solid #ebeced', borderRadius:12, padding:14, textAlign:'left', marginBottom:20 }}>
          <p style={{ fontSize:11, fontWeight:700, color:'#74777f', textTransform:'uppercase', marginBottom:8 }}>Ringkasan</p>
          {[
            ['Unit', profile?.nopol_assign],
            ['Jenis', jenis === 'Kerusakan Lainnya (isi manual)' ? jenisCustom : jenis],
            ['Urgensi', URGENSI.find(u=>u.value===urgensi)?.label],
            ['Foto', `${fotos.length} foto`],
          ].map(([k,v]) => (
            <div key={k} style={{ display:'flex', justifyContent:'space-between', marginBottom:6, fontSize:12 }}>
              <span style={{ color:'#74777f' }}>{k}</span>
              <span style={{ fontWeight:600 }}>{v}</span>
            </div>
          ))}
        </div>
        <button onClick={() => { setDone(false); setStep(1); setJenis(''); setJC(''); setUrgensi(''); setDeskripsi(''); setFotos([]); setLokasi(''); }}
          style={{ background:'#1a2b4b', color:'#fff', border:'none', borderRadius:10, padding:'12px 24px', fontSize:13, fontWeight:700, cursor:'pointer', fontFamily:'Montserrat,sans-serif' }}>
          Buat Laporan Baru
        </button>
      </div>
    </DriverLayout>
  );

  return (
    <DriverLayout title="Laporan Kerusakan" back>
      <div style={{ padding:16 }}>

        {/* Progress */}
        <div style={{ display:'flex', alignItems:'center', gap:6, marginBottom:20 }}>
          {[1,2,3].map(s => (
            <React.Fragment key={s}>
              <div style={{ width:28, height:28, borderRadius:'50%', display:'flex', alignItems:'center', justifyContent:'center', fontSize:11, fontWeight:700, background: step>=s ? '#1a2b4b' : '#e5e7eb', color: step>=s ? '#fff' : '#9ca3af' }}>
                {step > s ? '✓' : s}
              </div>
              {s < 3 && <div style={{ flex:1, height:2, borderRadius:1, background: step>s ? '#1a2b4b' : '#e5e7eb' }}/>}
            </React.Fragment>
          ))}
        </div>

        {/* STEP 1 */}
        {step === 1 && (
          <div>
            <p style={{ fontSize:14, fontWeight:700, marginBottom:4 }}>Jenis Kerusakan</p>
            <p style={{ fontSize:11, color:'#74777f', marginBottom:14 }}>Pilih kategori dan jenis kerusakan</p>

            {/* Info unit */}
            <div style={{ background:'#e8edf5', borderRadius:10, padding:'10px 14px', marginBottom:14, display:'flex', alignItems:'center', gap:10 }}>
              <span style={{ fontSize:20 }}>🚛</span>
              <div>
                <p style={{ fontSize:10, color:'#44474e' }}>Unit</p>
                <p style={{ fontSize:14, fontWeight:700, color:'#1a2b4b' }}>{profile?.nopol_assign || '—'}</p>
              </div>
            </div>

            {/* Accordion */}
            <div style={{ display:'flex', flexDirection:'column', gap:8, marginBottom:16 }}>
              {KATEGORI.map(kat => (
                <div key={kat.label} style={{ border:'1px solid #ebeced', borderRadius:10, overflow:'hidden', background:'#fff' }}>
                  <button onClick={() => setKatOpen(katOpen===kat.label ? null : kat.label)}
                    style={{ width:'100%', display:'flex', alignItems:'center', justifyContent:'space-between', padding:'12px 14px', background:'none', border:'none', cursor:'pointer', fontFamily:'Montserrat,sans-serif' }}>
                    <div style={{ display:'flex', alignItems:'center', gap:8 }}>
                      <span>{kat.icon}</span>
                      <span style={{ fontSize:13, fontWeight:600, color:'#1a1c1e' }}>{kat.label}</span>
                      {kat.items.some(i => i===jenis) && <span style={{ width:6, height:6, borderRadius:'50%', background:'#1a2b4b', display:'inline-block' }}/>}
                    </div>
                    <span style={{ color:'#c4c7cf', transition:'transform 0.2s', transform: katOpen===kat.label ? 'rotate(180deg)' : 'none' }}>▼</span>
                  </button>
                  {katOpen === kat.label && (
                    <div style={{ borderTop:'1px solid #f1f2f3', padding:'8px 14px 12px' }}>
                      {kat.items.map(item => (
                        <label key={item} style={{ display:'flex', alignItems:'center', gap:10, padding:'8px 10px', borderRadius:8, cursor:'pointer', background: jenis===item ? '#1a2b4b' : 'transparent', marginBottom:2 }}>
                          <input type="radio" name="jenis" checked={jenis===item} onChange={() => setJenis(item)} style={{ accentColor:'#fff' }}/>
                          <span style={{ fontSize:12, color: jenis===item ? '#fff' : '#1a1c1e' }}>{item}</span>
                        </label>
                      ))}
                    </div>
                  )}
                </div>
              ))}
            </div>

            {jenis === 'Kerusakan Lainnya (isi manual)' && (
              <input value={jenisCustom} onChange={e => setJC(e.target.value)} placeholder="Jelaskan jenis kerusakan..."
                style={{ width:'100%', border:'1px solid #c4c7cf', borderRadius:8, padding:'10px 12px', fontSize:12, fontFamily:'Montserrat,sans-serif', outline:'none', boxSizing:'border-box', marginBottom:14 }}/>
            )}

            {/* Urgensi */}
            {jenis && (
              <div style={{ marginBottom:16 }}>
                <p style={{ fontSize:12, fontWeight:700, marginBottom:8 }}>Tingkat Urgensi</p>
                <div style={{ display:'flex', flexDirection:'column', gap:8 }}>
                  {URGENSI.map(u => (
                    <label key={u.value} style={{ display:'flex', alignItems:'center', gap:12, padding:'10px 14px', border: urgensi===u.value ? `2px solid ${u.border}` : '1px solid #ebeced', borderRadius:10, cursor:'pointer', background: urgensi===u.value ? u.bg : '#fff' }}>
                      <input type="radio" name="urgensi" checked={urgensi===u.value} onChange={() => setUrgensi(u.value)} style={{ accentColor:'#1a2b4b' }}/>
                      <span style={{ fontSize:18 }}>{u.icon}</span>
                      <div>
                        <p style={{ fontSize:12, fontWeight:700, color: urgensi===u.value ? u.color : '#1a1c1e' }}>{u.label}</p>
                        <p style={{ fontSize:10, color: urgensi===u.value ? u.color : '#74777f' }}>{u.desc}</p>
                      </div>
                    </label>
                  ))}
                </div>
              </div>
            )}

            <button onClick={() => setStep(2)}
              disabled={!jenis || !urgensi || (jenis==='Kerusakan Lainnya (isi manual)' && !jenisCustom.trim())}
              style={{ width:'100%', background: (!jenis||!urgensi) ? '#9ca3af' : '#1a2b4b', color:'#fff', border:'none', borderRadius:10, padding:'13px 0', fontSize:13, fontWeight:700, cursor: (!jenis||!urgensi) ? 'not-allowed':'pointer', fontFamily:'Montserrat,sans-serif' }}>
              Lanjut →
            </button>
          </div>
        )}

        {/* STEP 2 */}
        {step === 2 && (
          <div>
            <p style={{ fontSize:14, fontWeight:700, marginBottom:4 }}>Detail Kerusakan</p>
            <p style={{ fontSize:11, color:'#74777f', marginBottom:14 }}>Jelaskan kondisi kerusakan secara detail</p>

            {/* Ringkasan step 1 */}
            <div style={{ background:'#f8f9fa', border:'1px solid #ebeced', borderRadius:10, padding:'10px 14px', display:'flex', justifyContent:'space-between', marginBottom:14 }}>
              <div>
                <p style={{ fontSize:10, color:'#74777f' }}>Jenis</p>
                <p style={{ fontSize:12, fontWeight:700 }}>{jenis === 'Kerusakan Lainnya (isi manual)' ? jenisCustom : jenis}</p>
              </div>
              {(() => { const u = URGENSI.find(x=>x.value===urgensi); return u ? (
                <span style={{ background:u.bg, color:u.color, padding:'4px 10px', borderRadius:20, fontSize:11, fontWeight:700, alignSelf:'center' }}>
                  {u.icon} {u.label}
                </span>
              ) : null; })()}
            </div>

            <div style={{ marginBottom:14 }}>
              <label style={{ display:'block', fontSize:10, fontWeight:700, color:'#44474e', textTransform:'uppercase', letterSpacing:'0.05em', marginBottom:5 }}>
                Deskripsi Kerusakan <span style={{ color:'#ba1a1a' }}>*</span>
              </label>
              <textarea rows={5} value={deskripsi} onChange={e => setDeskripsi(e.target.value)}
                placeholder="Ceritakan kondisi kerusakan secara detail. Kapan terjadi, gejala apa yang muncul, kondisi unit saat ini..."
                style={{ width:'100%', border:'1px solid #c4c7cf', borderRadius:10, padding:'10px 12px', fontSize:12, fontFamily:'Montserrat,sans-serif', resize:'none', outline:'none', boxSizing:'border-box' }}/>
              <p style={{ fontSize:10, color: deskripsi.length >= 10 ? '#10b981' : '#c4c7cf', textAlign:'right', marginTop:3 }}>
                {deskripsi.length} karakter {deskripsi.length < 10 ? '(min 10)' : '✓'}
              </p>
            </div>

            {urgensi === 'kritis' && (
              <div style={{ background:'#fff1f2', border:'1px solid #fecdd3', borderRadius:8, padding:'10px 14px', marginBottom:14, fontSize:11, color:'#9f1239', fontWeight:600 }}>
                🆘 Unit kritis! Setelah submit, segera hubungi admin atau dispatcher.
              </div>
            )}

            <div style={{ display:'flex', gap:8 }}>
              <button onClick={() => setStep(1)} style={{ flex:1, background:'#fff', color:'#1a2b4b', border:'1px solid #c4c7cf', borderRadius:8, padding:'11px 0', fontSize:12, fontWeight:700, cursor:'pointer', fontFamily:'Montserrat,sans-serif' }}>← Kembali</button>
              <button onClick={() => setStep(3)} disabled={deskripsi.length < 10}
                style={{ flex:1, background: deskripsi.length < 10 ? '#9ca3af' : '#1a2b4b', color:'#fff', border:'none', borderRadius:8, padding:'11px 0', fontSize:12, fontWeight:700, cursor: deskripsi.length < 10 ? 'not-allowed':'pointer', fontFamily:'Montserrat,sans-serif' }}>
                Lanjut →
              </button>
            </div>
          </div>
        )}

        {/* STEP 3 */}
        {step === 3 && (
          <div>
            <p style={{ fontSize:14, fontWeight:700, marginBottom:4 }}>Foto & Lokasi</p>
            <p style={{ fontSize:11, color:'#74777f', marginBottom:14 }}>Lampirkan foto kondisi unit dan lokasi</p>

            {/* Foto */}
            <div style={{ marginBottom:16 }}>
              <div style={{ display:'flex', justifyContent:'space-between', marginBottom:6 }}>
                <label style={{ fontSize:10, fontWeight:700, color:'#44474e', textTransform:'uppercase', letterSpacing:'0.05em' }}>Foto <span style={{ color:'#ba1a1a' }}>*</span></label>
                <span style={{ fontSize:10, color:'#c4c7cf' }}>{fotos.length}/5</span>
              </div>

              {fotos.length > 0 && (
                <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:8, marginBottom:10 }}>
                  {fotos.map((f,i) => (
                    <div key={i} style={{ position:'relative', aspectRatio:1 }}>
                      <img src={f.preview} alt="" style={{ width:'100%', height:'100%', objectFit:'cover', borderRadius:8, border:'1px solid #ebeced' }}/>
                      <button onClick={() => setFotos(p => p.filter((_,idx)=>idx!==i))}
                        style={{ position:'absolute', top:4, right:4, width:20, height:20, borderRadius:'50%', background:'#ba1a1a', color:'#fff', border:'none', cursor:'pointer', fontSize:12, display:'flex', alignItems:'center', justifyContent:'center' }}>×</button>
                    </div>
                  ))}
                  {fotos.length < 5 && (
                    <button onClick={() => fileRef.current?.click()}
                      style={{ aspectRatio:1, border:'2px dashed #c4c7cf', borderRadius:8, background:'#f8f9fa', cursor:'pointer', display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', color:'#74777f' }}>
                      <span style={{ fontSize:20 }}>+</span>
                      <span style={{ fontSize:9 }}>Tambah</span>
                    </button>
                  )}
                </div>
              )}

              {fotos.length === 0 && (
                <button onClick={() => fileRef.current?.click()}
                  style={{ width:'100%', border:'2px dashed #c4c7cf', borderRadius:10, padding:'24px 0', background:'#f8f9fa', cursor:'pointer', display:'flex', flexDirection:'column', alignItems:'center', gap:6, color:'#74777f' }}>
                  <span style={{ fontSize:32 }}>📷</span>
                  <span style={{ fontSize:12, fontWeight:600 }}>Ambil / Pilih Foto</span>
                  <span style={{ fontSize:10 }}>Maks 5 foto • JPG/PNG</span>
                </button>
              )}
              <input ref={fileRef} type="file" accept="image/*" multiple capture="environment" style={{ display:'none' }} onChange={handleFoto}/>
              {fotos.length === 0 && <p style={{ fontSize:10, color:'#ba1a1a', marginTop:4 }}>⚠ Minimal 1 foto wajib dilampirkan</p>}
            </div>

            {/* Lokasi */}
            <div style={{ marginBottom:16 }}>
              <label style={{ display:'block', fontSize:10, fontWeight:700, color:'#44474e', textTransform:'uppercase', letterSpacing:'0.05em', marginBottom:6 }}>
                Lokasi <span style={{ color:'#ba1a1a' }}>*</span>
              </label>
              <button onClick={ambilGPS} disabled={gpsLoad}
                style={{ width:'100%', border:`2px dashed ${lokasi ? '#10b981' : '#c4c7cf'}`, borderRadius:8, padding:'11px 0', background: lokasi ? '#f0fdf4':'#f8f9fa', cursor:'pointer', color: lokasi ? '#065f46':'#74777f', fontSize:12, fontWeight:600, fontFamily:'Montserrat,sans-serif', marginBottom:8 }}>
                {gpsLoad ? '⏳ Mengambil GPS...' : lokasi ? `✅ Koordinat: ${lokasi}` : '📍 Klik Ambil Lokasi GPS'}
              </button>
              <input value={lokasi} onChange={e => setLokasi(e.target.value)} placeholder="Atau isi manual: Jl. Raya Bekasi KM 25..."
                style={{ width:'100%', border:'1px solid #c4c7cf', borderRadius:8, padding:'9px 12px', fontSize:12, fontFamily:'Montserrat,sans-serif', outline:'none', boxSizing:'border-box' }}/>
            </div>

            <div style={{ display:'flex', gap:8 }}>
              <button onClick={() => setStep(2)} style={{ flex:1, background:'#fff', color:'#1a2b4b', border:'1px solid #c4c7cf', borderRadius:8, padding:'11px 0', fontSize:12, fontWeight:700, cursor:'pointer', fontFamily:'Montserrat,sans-serif' }}>← Kembali</button>
              <button onClick={handleSubmit} disabled={saving || fotos.length===0 || !lokasi.trim()}
                style={{ flex:2, background: (saving||fotos.length===0||!lokasi.trim()) ? '#9ca3af' : '#1a2b4b', color:'#fff', border:'none', borderRadius:8, padding:'11px 0', fontSize:12, fontWeight:700, cursor: saving ? 'not-allowed':'pointer', fontFamily:'Montserrat,sans-serif' }}>
                {saving ? 'Mengirim...' : 'Kirim Laporan'}
              </button>
            </div>
          </div>
        )}
      </div>
    </DriverLayout>
  );
}
